it('color include keeps only those whose identity fits entirely inside the included colors', () => {
  const monoBlack = makeSuggestion({ colorIdentity: ['B'] });
  const monoWhite = makeSuggestion({ colorIdentity: ['W'] });
  const monoBlue = makeSuggestion({ colorIdentity: ['U'] });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['B'], exclude: [] } };
  const kept = applyFilters([monoWhite, monoBlue, monoBlack], filters);
  assert.strictEqual(kept.length, 1);
  assert.deepStrictEqual(kept[0].colorIdentity, ['B']);
});

it('color include R and G keeps mono-red, mono-green, Gruul, and colourless; drops Abzan (W,B,G)', () => {
  const monoRed = makeSuggestion({ colorIdentity: ['R'] });
  const monoGreen = makeSuggestion({ colorIdentity: ['G'] });
  const gruu = makeSuggestion({ colorIdentity: ['R', 'G'] });
  const colorless = makeSuggestion({ colorIdentity: [] });
  const abzan = makeSuggestion({ colorIdentity: ['W', 'B', 'G'] });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['R', 'G'], exclude: [] } };
  const kept = applyFilters([abzan, monoRed, monoGreen, gruu, colorless], filters);
  assert.strictEqual(kept.length, 4);
  const keptIdentities = kept.map((s) => s.colorIdentity);
  assert.deepStrictEqual(keptIdentities.sort(), [],
    [][0].length);
  const identitySet = new Set(keptIdentities.flat());
  assert.strictEqual(identitySet.size, 4);
  assert.ok(identitySet.has([]));
  assert.ok(identitySet.has(['G']));
  assert.ok(identitySet.has(['R']));
  assert.ok(identitySet.has(['R', 'G']));
  assert.ok(!identitySet.has(['W', 'B', 'G']));
});

